#!/usr/bin/env python3
# reserve_L35c.py — 새 과 L35c(와인 테라스의 사흘째 · 세계 s35 의 c) — 캠벨 24장 종분화 전부 + 22장 J0-44(점진 · 단속).
#  L13c 부터의 방식 — 「둑으로 갈린 두 연못 앞, 중매쟁이 할머니의 합동 혼례가 짝마다 틀어지는」 한 장면(Gemini 가 통째로 그림 + 구역 편집 + PIL).
import json
P = '/tmp/b2/tools/hooks.json'
txt = open(P, encoding='utf-8').read(); d = json.loads(txt)
assert json.dumps(d, ensure_ascii=False, indent=1) == txt
R = d['_심볼예약']
B = '[2026-11-16 새 과 L35c]'
new = {
 '이마를 짚고 진땀 흘리는 한복 중매쟁이 할머니(눈가리개 없음) + 붉은 꽃무늬 포대기에 업혀 손을 흔드는 손주': f'생물학적 종 개념(마이어 — 자연에서 교배해 생존 · 번식 가능한 자손 · 기준은 생식적 격리) 전용 {B} — L35c s2. 업힌 손주 = 자식이 또 자식을 낳는다 = 번식 가능한 자손. L35a 의 그 할머니(【붉은 천으로 눈을 가린 사람】 = 무작위 교배)가 오늘은 눈가리개를 벗었다 — 「보고 고른다」가 아니라 「손주를 볼 수 있느냐」. ⚠ 【머릿수건 할머니 중매쟁이가 두 짚단을 …】(L48f 접합)과 가른다 — 이쪽은 한복 · 혼례상 · 손주, 짚 띠 없음.',
 '할머니 손의 붉은 실패 — 상 왼쪽으로 뻗어 끊어진 붉은 실 / 상 오른쪽으로 뻗어 두 도롱뇽을 묶은 붉은 실 매듭': f'생식 장벽 8 = 접합 전 5(묶이지도 못함 = 수정 자체를 막음) + 접합 후 3(묶였는데 새끼에게서 탈) 전용 {B} — L35c s4. 붉은 실 = 인연의 실(중매). 혼례상 = 가운데 금. ⚠ 밧줄(DNA) · 짚끈 · 검은 전선 매듭(신경절)과 가른다 — 이쪽은 가는 붉은 실과 나무 실패.',
 '노란 줄자를 감은 물고기 뼈 화석 돌판': f'종 개념의 한계 — 화석(교배를 시험할 수 없음) · 형태종(몸의 꼴 · 구조로 가름 = 줄자) 전용 {B} — L35c s3. ⚠ 【삼엽충 화석 위아래로 지나는 검은 화산재 줄 …】(방사성 연대) · 【… 진흙에 덮인 죽은 물고기 뼈】(화석이 되는 길)과 가른다 — 이쪽은 줄자가 감겨 혼례상 앞에 줄 선 돌판.',
 '제 몸을 찢어 둘이 되는 주황 불가사리 + 곁에 줄지어 선 점점 작은 불가사리': f'종 개념의 한계 — 무성생식(짝짓기 잣대가 없음) · 계통종(공통 조상에서 갈라진 가장 작은 무리) 전용 {B} — L35c s3. 주황 불가사리 = 무성생식(【같은 꼴 주황 불가사리들 …】 L51a)과 같은 뜻 줄기.',
 '물풀을 문 검은 오리 · 물고기를 문 흰 오리 사이의 검정 · 하양 얼룩 새끼': f'종 개념의 한계 — 생김새가 달라도 교배해 유전자가 오감(그롤라곰 — 곰은 그리지 않음: 【북극곰】 = 쌍극세포) · 생태종(먹이 = 생태적 지위) 전용 {B} — L35c s3. 얼룩 새끼 = 잡종 — s17 물목의 얼룩 새끼들과 같은 꼴.',
 '사과 · 산사 열매를 하나씩 끌어안고 뾰로통한 띠 날개 파리 둘': f'서식지 격리(라골레티스 사과파리 — 산사나무 vs 사과) 전용 {B} — L35c s5. ⚠ 【뚜껑 달린 상자 셋을 한 줄로 이어 지은 상자 초파리 …】(초파리 유전학)와 가른다 — 이쪽은 날개에 검은 띠가 있는 맨 파리 · 열매를 끌어안음.',
 '반은 한여름(매미 · 아지랑이 · 밀짚모자에 땀) · 반은 눈 덮인 겨울(고드름 · 웅크려 떪)로 갈린 벤치의 스컹크 둘': f'시간 격리(점박이스컹크 — 늦여름 vs 늦겨울 교미) 전용 {B} — L35c s6. ⚠ 【햇볕에도 목도리에 하품하는 통통한 사람 / 땀에 젖어 부채질하는 깡마른 사람】(갑상샘)과 가른다 — 스컹크 · 벤치 하나에 두 계절 · 부채 · 목도리 없음. ⚠ 여름 표지로 해바라기를 넣었다가 매미로 갈았다(해바라기 = 팽압 L53b).',
 '파란 발 하나를 높이 들고 부리를 하늘로 쳐든 푸른발부비새 수컷 + 고개 돌려 하품하는 빨간 발 암컷': f'행동 격리(구애 행동이 종마다 다름 — 푸른발부비새의 구애 춤) 전용 {B} — L35c s7. ⚠ 하품은 지루함 — 【햇볕에도 목도리에 하품하는 …】(갑상샘저하) · 잠옷 병정(L13a) · 탑 벽에 기댄 벌과 가른다.',
 '몸을 맞대 보지만 맞지 않아 진땀 흘리며 더듬이를 비튼 맨 달팽이 둘': f'기계적 격리(생식 기관의 꼴 · 구조가 맞지 않음 — 껍데기 나선 방향이 반대인 달팽이) 전용 {B} — L35c s8. ⚠ 【… 넥타이와 머리 리본을 함께 단 달팽이 …】(자웅동체) · 만년필 달팽이(디펜신) · 구리 냄비 달팽이(헤모시아닌)와 가른다 — 이쪽은 아무것도 걸치지 않은 맨 달팽이.',
 '붉은 성게 · 보라 성게 사이에 뜬 큰 주황 알 여섯 + 알에 부딪혀 굵은 곡선을 그리며 튕겨 나가는 흰 정자(알 속엔 없음)': f'배우자 격리(정자 · 난자 표면 단백질이 결합하지 못함 — 성게) 전용 {B} — L35c s9. ⚠ 【알 구름 뿌리는 물고기 …】(체외수정 L51a)와 가른다 — 이쪽은 성게 · 알이 낱알 · 닿아도 튕김. ⚠ 【드릴 모자 · 동전 목걸이 · 긴 꼬리의 하얀 헤엄꾼】(정자 L51a)과 달리 흰 올챙이 꼴. ⚠ 닿은 자리의 작은 흰 불꽃은 「수정 성공」으로 읽혔다(일치 검사 4회) — 알을 키우고 굵은 곡선으로 튕김을 보였다.',
 '깨진 알 속의 반반 무늬 도롱뇽 새끼(창백 · 이마에 물수건) + 눈물 글썽이며 내려다보는 주황 · 노란 점박이 검은 도롱뇽': f'잡종 생존력 저하(엔사티나 도롱뇽 — 접합 후 장벽의 첫째) 전용 {B} — L35c s10. ⚠ 【열이 드나드는 네 길(… 얼음덩이)】 · 빨간 온도계와 가른다 — 열 표지는 물수건 하나.',
 '몸 · 갈기 · 꼬리는 말, 긴 귀는 당나귀인 갈색 노새 + 덮개 젖힌 텅 빈 유모차의 거미줄 + 흰 말 · 잿빛 당나귀': f'잡종 불임(노새 = 말 × 당나귀 — 튼튼하나 새끼를 못 낳음 · 접합 후) 전용 {B} — L35c s11. 거미줄 = 오래 멈춤(L37b) · 빈 유모차 = 새끼 없음. ⚠ 【갈색 조랑말 수레 …】(수동면역)와 가른다 — 수레 없음 · 젖병 없음(【젖병 유모】 = 인히빈).',
 '금빛 이삭이 묵직한 큰 벼 한 포기 둘레의 작달막한 · 누렇게 쓰러진 벼': f'잡종 붕괴(F₁ 은 정상 · F₂ 이후가 약하거나 불임 — 재배 벼) 전용 {B} — L35c s12. ⚠ 흰 쌀밥 공기(라이신)와 가른다 — 논의 포기.',
 '칸막이 없는 흰 구슬 연못에서 빛깔끼리만 입 맞추는 빨강 · 파랑 물고기 + 빨간 꼬리에 맞아 눈이 핑핑 돌며 튕겨 나가는 파란 물고기': f'동소적 종분화 · 성선택(빅토리아호 시클리드) 전용 {B} — L35c s14. ⚠ 빨간 하트 없음(하트 = 성) · 【… 분홍 · 파랑 반반 물고기】(성전환 L51a)와 가른다 — 온통 한 빛깔.',
 '자루 셋(둘은 끈으로 묶이고 하나 홀로)을 멘 채 씨 없는 수박을 들고 우는 아이 + 머리 양옆에 자루 둘을 든 엄마': f'3배체(3n) — 짝이 안 맞아 불임 · 씨 없는 수박 전용 {B} — L35c s16. 자루 = 【사람이 멘 자루 개수】(배수성) · 묶인 둘 = 짝지은 상동 · 홀로 하나 = 짝 없음. ⚠ 【A 자 접이 사다리 위 쌍둥이 벌의 이음 깃발 … + 우는 아이의 큰 눈물방울 …】(IgA)과 가른다 — 이쪽 눈물에는 깃발이 없다. 수박은 이 과에서 3n 전용 — 다른 판에 수박을 그리지 마라.',
 '머리에 흰 수건을 동인 농부의 자루 여섯(베이지 · 초록 · 금빛 둘씩 · 밀 이삭) + 이삭 늘어진 귀리 다발 · 목화 · 감자 · 끈으로 묶은 담뱃잎 다발(푸른 잎 · 말린 금빛 잎) 수레': f'배수체 작물(밀 = 세 종의 세트가 둘씩 = 6n · 귀리 · 목화 · 감자 · 담배) 전용 {B} — L35c s16. ⚠ 【삽으로 뜬 진흙 덩이 … 밀짚모자 농부】(분변 이식) · 【밀 이삭을 수놓은 흰 레이스 앞치마 일꾼의 가위 …】(아밀레이스)와 가른다 — 수건 · 앞치마 없음 · 담배는 넓은 잎(궐련 = 니코틴).',
 '둑 끝 물목의 세 갈래 — 천 모자 일꾼 둘이 돌을 쌓아 높임(발치에 늘어진 얼룩 새끼) / 허물어진 둑 끝에서 섞여 헤엄치는 검은 · 흰 오리 / 물속 돌담 사이 틈을 줄지어 지나는 얼룩 새끼 셋': f'잡종 지대와 그 끝 셋 — 강화(잡종 적응도 낮음 → 접합 전 장벽 강해짐) · 융합 · 안정 전용 {B} — L35c s17. ⚠ 삽 · 모래주머니 없음(【삽날에 노란 유리판 …】 · 【삽으로 뜬 진흙 덩이 …】 · 사람이 멘 자루 = 배수성) — 맨손으로 돌을 쌓는다.',
 '거미줄 · 먼지를 뒤집어쓰고 거인 돌계단(긴 층계참 + 갑자기 높은 단)을 뛰어오르는 치타 / 모래 비탈을 쉬지 않고 오르는 거북': f'단속평형설(긴 정체 + 종분화 때 짧은 급변) ↔ 계통점진설(일정 · 점진) 전용 {B} — L35c s18. 거미줄 = 오래 멈춤 · 거북 = 느림(L13g)과 같은 뜻 줄기. ⚠ 토끼 없음(【흙바닥에 앉은 토끼】 = 시토키닌 — 「토끼와 거북」의 토끼 자리에 치타).',
}
for k, v in new.items():
    assert k not in R, k
    R[k] = v
def add(key, note):
    v = R[key]; assert isinstance(v, str), key
    R[key] = v + ' ' + note
add('검은 · 흰 유리구슬이 든 연못', f'★ {B} L35c — 흙둑이 수평선까지 연못을 둘로 갈라 왼쪽은 검은 구슬 · 오른쪽은 흰 구슬투성이 = 지리적으로 갈린 두 집단이 따로 변함(이소적 종분화 · s1 · s13). 오른쪽 흰 구슬 연못 속 빨강 · 파랑 물고기 = 동소적(s14).')
add('나무 수문', f'★ {B} L35c — 둑의 수문에 널빤지 두 장이 가위표로 박혀 꽉 막힘 = 유전자 흐름이 끊김 → 종분화 시작(s13).')
add('못에 걸고 널빤지 둘로 가위표 친 물건', f'★ {B} L35c s13 — 둑의 나무 수문에 가위표 = 흐름을 「안 쓴다」(끊김).')
add('사람이 멘 자루 개수', f'★ {B} L35c 오른쪽 데크의 하객 — 아빠 베이지 넷(4n 동질배수체) · 엄마 베이지 둘(2n) · 아이 셋(둘은 끈으로 묶고 하나 홀로 = 3n 불임 · 씨 없는 수박) · 노란 꽃 젊은이 베이지 둘 + 초록 둘(이질배수체 — 두 종의 세트) · 농부 여섯(베이지 · 초록 · 금빛 둘씩 = 밀 6n). 빛깔 = 어느 종의 세트인가.')
add('같은 꼴 주황 불가사리들(잘린 팔 토막 · 싹 · 갈라짐 · 혼자 품은 알 둥지 · 보라 점 하나)', f'★ {B} L35c s3 — 혼례상 앞에서 제 몸을 찢어 둘이 되는 불가사리와 줄지어 선 작은 불가사리 = 무성생식이라 생물학적 종 개념을 쓸 수 없음 · 갈라져 나온 무리 = 계통종.')
add('와인병 · 와인 통', f'★ {B} L35c 와인 테라스의 사흘째 — 와인 통 뚜껑 위의 달팽이 둘(기계적 격리).')
add('붉은 천으로 눈을 가린 사람', f'★ {B} L35c s2 — 같은 한복 할머니가 오늘은 눈가리개를 벗고 손주를 업었다 = 생물학적 종 개념(무작위가 아님).')
add('A 자 접이 사다리 위 쌍둥이 벌의 이음 깃발(Y 둘을 깃대 끝끼리 J 자 쇠고리로) + 우는 아이의 큰 눈물방울 · 샘물 속 작은 이음 깃발', f'★ {B} L35c s16 의 우는 아이(씨 없는 수박 · 자루 셋)는 IgA 와 무관 — 눈물에 깃발이 없다.')
add('부표 머리 둘을 납작 누른 나무 판자 벽 + 꼿꼿한 해바라기 + 아래 물의 사과 · 포도 더미로 몰린 파란 물방울', f'★ {B} L35c 벤치의 여름 표지로 해바라기를 그렸다가 이 예약 때문에 매미로 갈았다 — 해바라기는 여전히 L53b 전용.')
add('햇볕에도 목도리에 하품하는 통통한 사람 / 땀에 젖어 부채질하는 깡마른 사람', f'★ {B} L35c 의 하품하는 빨간 발 부비새(지루함 · 행동 격리) · 밀짚모자에 땀 흘리는 여름 스컹크(시간 격리)는 이 뜻이 아니다 — 사람 · 목도리 · 부채가 없다.')
out = json.dumps(d, ensure_ascii=False, indent=1)
assert json.loads(out) == d
open(P, 'w', encoding='utf-8').write(out)
print('예약', len(R))
